def solve_sequence(limit):
    a = [0] * (limit + 1)
    a[1] = 1
    a[2] = 1
    for n in range(3, limit + 1):
        prev_a = a[n-1]
        if not (1 <= prev_a < n):
            return None, n
        a[n] = a[prev_a] + a[n - prev_a]
        if a[n] < a[n-1]:
            return None, n
    return a, None

